// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type NamePlaceholderProps = Record<string, any>;

const NamePlaceholder: React.FC<NamePlaceholderProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  cardBackgroundColor = "#111111",
  accentColor = "#ff2a85", // Vibrant pink
  textColor = "#ffffff",
  nameText = "Malloy Studio",
  roleText = "Creative Director",
  iconImage = "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=400&auto=format&fit=crop", // Abstract clean placeholder
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const s = Math.min(width, height);
  const cardHeight = s * 0.22; // Slightly taller to accommodate role
  const iconSize = cardHeight * 0.65;

  // Animations
  const cardEntrySpring = spring({
    frame,
    fps,
    config: {
      damping: 14,
      mass: 0.8,
      stiffness: 100,
    },
  });

  const cardTranslateY = interpolate(cardEntrySpring, [0, 1], [s * 0.2, 0]);
  const cardOpacity = interpolate(cardEntrySpring, [0, 0.5], [0, 1]);

  const iconSpring = spring({
    frame: frame - 10,
    fps,
    config: {
      damping: 10,
      mass: 0.5,
      stiffness: 150,
    },
  });

  const iconScale = interpolate(iconSpring, [0, 1], [0, 1]);
  const iconRotate = interpolate(iconSpring, [0, 1], [-30, 0]);

  const textSpring = spring({
    frame: frame - 20,
    fps,
    config: {
      damping: 12,
      stiffness: 90,
    },
  });

  const textTranslateX = interpolate(textSpring, [0, 1], [-30, 0]);
  const textOpacity = interpolate(textSpring, [0, 1], [0, 1]);

  // Exit animation (starts 1 second before end)
  const exitFrame = frame - (durationInSeconds * fps - fps);
  const exitSpring = spring({
    frame: exitFrame,
    fps,
    config: {
      damping: 15,
    },
  });

  const exitTranslateY = interpolate(exitSpring, [0, 1], [0, s * 0.2]);
  const exitOpacity = interpolate(exitSpring, [0, 1], [1, 0]);

  // Combine entry and exit
  const finalTranslateY = cardTranslateY + exitTranslateY;
  const finalOpacity = Math.min(cardOpacity, exitOpacity);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceGroteskFamily,
        alignItems: "flex-start",
        justifyContent: "flex-end",
        padding: `${s * 0.08}px`,
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          backgroundColor: cardBackgroundColor,
          height: `${cardHeight}px`,
          minWidth: `${width * 0.45}px`, // Makes the card significantly wider left to right
          padding: `0 ${width * 0.08}px 0 ${width * 0.02}px`,
          borderRadius: `${cardHeight / 2}px`,
          borderLeft: `${s * 0.015}px solid ${accentColor}`,
          boxShadow: `0 20px 40px rgba(0,0,0,0.5), -5px 0 20px ${accentColor}40`,
          opacity: finalOpacity,
          transform: `translateY(${finalTranslateY}px)`,
          transition: "none",
        }}
      >
        <div
          style={{
            width: `${iconSize}px`,
            height: `${iconSize}px`,
            borderRadius: "50%",
            overflow: "hidden",
            marginRight: `${width * 0.02}px`,
            backgroundColor: `${accentColor}20`,
            border: `2px solid ${accentColor}80`,
            transform: `scale(${iconScale}) rotate(${iconRotate}deg)`,
            opacity: interpolate(iconScale, [0, 0.5], [0, 1]),
            flexShrink: 0,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
          }}
        >
          <Img
            src={iconImage}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              transition: "none",
            }}
          />
        </div>

        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            transform: `translateX(${textTranslateX}px)`,
            opacity: textOpacity,
            transition: "none",
          }}
        >
          <h1
            style={{
              color: textColor,
              fontSize: `${cardHeight * 0.32}px`,
              fontWeight: 700,
              margin: 0,
              lineHeight: 1.1,
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            {nameText}
          </h1>
          <h2
            style={{
              color: textColor,
              opacity: 0.75,
              fontSize: `${cardHeight * 0.18}px`,
              fontWeight: 400,
              margin: `${cardHeight * 0.05}px 0 0 0`,
              lineHeight: 1.1,
              letterSpacing: "0.01em",
              transition: "none",
            }}
          >
            {roleText}
          </h2>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default NamePlaceholder;